describe('Export Personal Data as JSON', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.login('testuser@example.com', 'password123');
    cy.navigateTo('/profile');
  });

  it('should successfully export personal data as JSON file', () => {
    cy.get('[data-testid="export-data-button"]').should('be.visible').click();

    cy.get('[data-testid="export-format-select"]').should('be.visible');
    cy.get('[data-testid="export-format-option-json"]').click();

    cy.get('[data-testid="confirm-export-button"]').should('be.enabled').click();

    cy.readFile('cypress/downloads/personal_data.json').should('exist');

    cy.readFile('cypress/downloads/personal_data.json').then((fileContent) => {
      const data = JSON.parse(fileContent);
      expect(data).to.have.property('email');
      expect(data).to.have.property('firstName');
      expect(data).to.have.property('lastName');
      expect(data).to.have.property('createdAt');
      expect(data.email).to.equal('testuser@example.com');
    });

    cy.get('[data-testid="export-success-message"]')
      .should('be.visible')
      .and('contain', 'Your data has been exported successfully');
  });

  it('should handle export with empty optional fields gracefully', () => {
    cy.get('[data-testid="profile-edit-button"]').click();
    cy.get('[data-testid="phone-input"]').clear();
    cy.get('[data-testid="company-input"]').clear();
    cy.get('[data-testid="save-profile-button"]').click();
    cy.get('[data-testid="save-success-message"]').should('be.visible');

    cy.get('[data-testid="export-data-button"]').click();
    cy.get('[data-testid="export-format-option-json"]').click();
    cy.get('[data-testid="confirm-export-button"]').click();

    cy.readFile('cypress/downloads/personal_data.json').then((fileContent) => {
      const data = JSON.parse(fileContent);
      expect(data).to.have.property('email');
      expect(data.phone).to.be.null;
      expect(data.company).to.be.null;
      expect(Object.keys(data).length).to.be.greaterThan(0);
    });
  });

  it('should prevent export when user is not authenticated', () => {
    cy.logout();
    cy.visit('/profile');
    cy.url().should('include', '/login');
    cy.get('[data-testid="export-data-button"]').should('not.exist');
  });

  it('should display loading state during export process', () => {
    cy.get('[data-testid="export-data-button"]').click();
    cy.get('[data-testid="export-format-option-json"]').click();
    cy.get('[data-testid="confirm-export-button"]').click();

    cy.get('[data-testid="export-loading-spinner"]').should('be.visible');
    cy.get('[data-testid="confirm-export-button"]').should('be.disabled');

    cy.get('[data-testid="export-success-message"]', { timeout: 10000 }).should('be.visible');
    cy.get('[data-testid="export-loading-spinner"]').should('not.exist');
  });

  it('should handle export failure gracefully', () => {
    cy.intercept('POST', '/api/export/data', { statusCode: 500, body: { error: 'Server error' } }).as('exportFail');

    cy.get('[data-testid="export-data-button"]').click();
    cy.get('[data-testid="export-format-option-json"]').click();
    cy.get('[data-testid="confirm-export-button"]').click();

    cy.wait('@exportFail');

    cy.get('[data-testid="export-error-message"]')
      .should('be.visible')
      .and('contain', 'Failed to export data');

    cy.get('[data-testid="retry-export-button"]').should('be.visible');
  });
});
